import re, os

def find_multicatch_candidates(filepath):
    with open(filepath) as f:
        lines = f.readlines()

    results = []
    i = 0
    while i < len(lines):
        line = lines[i]
        m1 = re.search(r'} catch \((\w+(?:\.\w+)*)\s+(\w+)\) \{', line)
        if m1:
            # find end of this catch block
            depth = 1
            j = i + 1
            body1 = []
            while j < len(lines) and depth > 0:
                if '{' in lines[j]:
                    depth += lines[j].count('{')
                if '}' in lines[j]:
                    depth -= lines[j].count('}')
                if depth > 0:
                    body1.append(lines[j].strip())
                j += 1

            # Now look for the next catch block starting at j-1
            if j < len(lines):
                m2 = re.search(r'} catch \((\w+(?:\.\w+)*)\s+(\w+)\) \{', lines[j-1])
                if m2:
                    depth2 = 1
                    k = j
                    body2 = []
                    while k < len(lines) and depth2 > 0:
                        if '{' in lines[k]:
                            depth2 += lines[k].count('{')
                        if '}' in lines[k]:
                            depth2 -= lines[k].count('}')
                        if depth2 > 0:
                            body2.append(lines[k].strip())
                        k += 1

                    if body1 == body2 and body1:
                        results.append({
                            'line1': i+1,
                            'type1': m1.group(1),
                            'var1': m1.group(2),
                            'type2': m2.group(1),
                            'var2': m2.group(2),
                            'body': body1[:3],
                        })
        i += 1
    return results

