import re, os

# Look for specific catch patterns: "throw e;" which would be multi-catch candidates
# and other simple rethrows

modules = [
    "server/src/main/java",
    "metadata/src/main/java",
    "raft/src/main/java",
    "storage/src/main/java",
    "group-coordinator/src/main/java",
    "coordinator-common/src/main/java",
    "clients/src/main/java",
    "connect/runtime/src/main/java",
]

# Search for: } catch (X e) {\n    throw e;\n} catch (Y e) {\n    throw e;\n}
pattern = re.compile(
    r'}\s*catch\s*\(\s*([\w.]+)\s+(\w+)\s*\)\s*\{\s*\n\s*throw\s+\2\s*;\s*\n\s*}\s*catch\s*\(\s*([\w.]+)\s+(\w+)\s*\)\s*\{\s*\n\s*throw\s+\4\s*;\s*\n',
    re.MULTILINE
)

for module in modules:
    if not os.path.exists(module):
        continue
    for root, dirs, files in os.walk(module):
        for fname in sorted(files):
            if not fname.endswith(".java"):
                continue
            fpath = os.path.join(root, fname)
            try:
                content = open(fpath).read()
            except:
                continue

            for m in pattern.finditer(content):
                exc1 = m.group(1)
                exc2 = m.group(3)
                if exc1 != exc2:
                    line_no = content[:m.start()].count('\n') + 1
                    print(f"{fpath}:{line_no}: catch({exc1} | {exc2})")
EOF

